const body = $input.first().json.body || $input.first().json;
const rawPrompt = String(body.prompt || '');
let masked = rawPrompt;
const maskedTypes = [];

const bankRe = /\b(stk|số\s+tài\s+khoản|so\s+tai\s+khoan|tài\s+khoản|tai\s+khoan|account(?:\s+no\.?|\s+number)?)\s*([:#-]?)\s*(\d{9,16})\b/gi;
if (bankRe.test(masked)) {
  maskedTypes.push('bank_account');
  masked = masked.replace(bankRe, '$1$2 [REDACTED_BANK_ACCOUNT]');
}
const emailRe = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g;
if (emailRe.test(masked)) {
  maskedTypes.push('email');
  masked = masked.replace(emailRe, '[REDACTED_EMAIL]');
}
const phoneRe = /(?<!\d)(?:\+84|0)(?:3|5|7|8|9)\d{8}(?!\d)/g;
if (phoneRe.test(masked)) {
  maskedTypes.push('phone');
  masked = masked.replace(phoneRe, '[REDACTED_PHONE]');
}
const cccdRe = /(?<!\d)\d{12}(?!\d)/g;
if (cccdRe.test(masked)) {
  maskedTypes.push('cccd');
  masked = masked.replace(cccdRe, '[REDACTED_CCCD]');
}

return [{
  json: {
    prompt: masked,
    masked_types: maskedTypes,
    jwt_token: String(body.jwt_token || ''),
    chat_user_id: String(body.chat_user_id || 'anonymous'),
    export_format: String(body.export_format || 'csv')
  }
}];

const inbound = $('Safety_Relay_Mask_PII').first().json;
const llmResp = $input.first().json;
const choices = Array.isArray(llmResp.choices) ? llmResp.choices : [];
const rawSql = String((choices[0] && choices[0].message && choices[0].message.content) || '');
const cleanSql = rawSql.replace(/^```(?:sql)?\s*/i, '').replace(/\s*```$/i, '').trim();
const usage = llmResp.usage || {};
return [{
  json: {
    sql: cleanSql,
    jwt_token: inbound.jwt_token,
    chat_user_id: inbound.chat_user_id,
    export_format: inbound.export_format,
    model: llmResp.model || 'yggdrasil-default-llm',
    prompt_tokens: Number(usage.prompt_tokens || 0),
    completion_tokens: Number(usage.completion_tokens || 0),
    total_tokens: Number(usage.total_tokens || 0)
  }
}];
